begin
  FileName := FormatFloat('000', GetCurrentMarkedFileIndex) + ' ' + FileName;
end.

Use modified date:
begin
  FileName := FormatDateTime('yyyy-mm-dd', FileTimeModified(FilePath)) + ' ' + FileName;
end.

Use image metadata:
var Value: WideString;
begin
  Value := CalculateMetaTag(FilePath, 'EXIF_Model');
  if Value <> '' then FileName := Value + ' ' + FileName;
end.

Rearrange underscore parts:
var Parts: TWideStringArray;
begin
  Parts := WideSplitString(WideExtractBaseName(FileName), '_');
  if Length(Parts) = 2 then FileName := Parts[1] + '_' + Parts[0] + WideExtractFileExt(FileName);
end.
